style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com"), domain("web.roblox.com"), domain("create.roblox.com") {
:root{
    --bg:        #121216;   /* tło strony, niepełna czerń */
    --bg-soft:   #17171c;   /* paski/topbar */
    --panel:     #1b1b21;   /* karty/panele/modale */
    --border:    #23232a;
    --text:      #e9e9ef;
    --muted:     #a2a7b0;
    --accent:    #ff6ea8;   /* różowe akcenty */
    --accent-2:  #ff8dbb;   /* hover/active */
    --shadow:    0 6px 24px rgba(0,0,0,.35);
  }

  /* global */
  html, body{
    background: var(--bg) !important;
    color: var(--text) !important;
  }
  *{
    scrollbar-color: var(--accent) var(--bg-soft);
  }
  ::selection{ background: var(--accent-2); color:#0b0b0e; }

  /* główne kontenery/karty */
  .container, .content, .page-content, .section,
  .card, .box, .modal, .dropdown-menu, .popover,
  [class*="Card"], [class*="Panel"], [class*="Modal"],
  [class*="container"], [class*="panel"], [class*="card"]{
    background: var(--panel) !important;
    color: var(--text) !important;
    border-color: var(--border) !important;
    box-shadow: var(--shadow) !important;
  }

  /* topbar / nav / footer */
  header, nav, .rbx-navbar, [class*="Header"], [class*="Navbar"], footer{
    background: var(--bg-soft) !important;
    color: var(--text) !important;
    border-color: var(--border) !important;
  }

  /* linki */
  a{ color: var(--accent) !important; }
  a:hover, a:focus{ color: var(--accent-2) !important; text-decoration: underline; }

  /* przyciski */
  button, [role="button"], .btn, .btn-primary, .btn-common{
    background: var(--accent) !important;
    color:#0b0b0e !important;
    border: 1px solid transparent !important;
    border-radius: 10px !important;
  }
  button:hover, [role="button"]:hover, .btn:hover, .btn-primary:hover{
    background: var(--accent-2) !important;
    filter: saturate(1.02) !important;
  }
  /* przyciski „secondary” */
  .btn-secondary, .btn-default, .btn-outline, .btn-inactive{
    background: var(--bg-soft) !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
  }
  .btn-secondary:hover, .btn-default:hover, .btn-outline:hover{
    background: #202029 !important;
  }

  /* inputy / formularze / wyszukiwarka */
  input, textarea, select, .input, .form-control{
    background: #1c1c23 !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
    border-radius: 10px !important;
    box-shadow: none !important;
  }
  input::placeholder, textarea::placeholder{ color: var(--muted) !important; }
  label, .help-block, .text-muted{ color: var(--muted) !important; }

  /* listy, tabele, menu */
  table, thead, tbody, tr, th, td,
  .menu, .menu-item, [class*="Menu"], [class*="Dropdown"]{
    background: var(--panel) !important;
    color: var(--text) !important;
    border-color: var(--border) !important;
  }

  /* karty/thumbnail’e – lekkie przyciemnienie tła pod grafiką */
  .thumbnail, [class*="Thumbnail"], .game-card, [class*="GameCard"]{
    background: #18181e !important;
    border-color: var(--border) !important;
  }

  /* badge/pill/tag */
  .badge, .label, [class*="Tag"], [class*="Pill"]{
    background: var(--accent) !important;
    color:#0b0b0e !important;
    border: none !important;
  }

  /* modal overlay */
  .modal-backdrop, [class*="Backdrop"], [class*="Overlay"]{
    background: rgba(0,0,0,.6) !important;
  }

  /* bordery i separatory */
  hr, .divider, [class*="Divider"]{ border-color: var(--border) !important; }

  /* scrollbary (Chromium) */
  ::-webkit-scrollbar{ width: 12px; height: 12px; }
  ::-webkit-scrollbar-track{ background: var(--bg-soft); }
  ::-webkit-scrollbar-thumb{
    background: var(--accent);
    border: 3px solid var(--bg-soft);
    border-radius: 999px;
  }
  ::-webkit-scrollbar-thumb:hover{ background: var(--accent-2); }
}
